import { ok } from './result.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';

function daysBetween(startDate, endDate) {
  const start = new Date(startDate + 'T00:00:00Z');
  const end = new Date(endDate + 'T00:00:00Z');
  const msPerDay = 24 * 60 * 60 * 1000;
  return Math.floor((end - start) / msPerDay);
}

export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => {
      if (!inv.number) return false;
      if (inv.status !== 'issued' && inv.status !== 'partially_paid') return false;
      if (!inv.dueDate) return false;
      return inv.dueDate < asOf;
    })
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return ok(overdue);
}

export function vatSummary(invoices) {
  const vatByRate = {};

  for (const invoice of invoices) {
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    if (!invoice.lines) continue;

    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const total = lineTotal(line);
      const discount = lineDiscount(line);
      const base = total - discount;
      const vat = lineVat(line);

      if (!vatByRate[rate]) {
        vatByRate[rate] = { rate, base: 0, vat: 0 };
      }

      vatByRate[rate].base += base;
      vatByRate[rate].vat += vat;
    }
  }

  const result = Object.values(vatByRate).sort((a, b) => b.rate - a.rate);
  return ok(result);
}

