test('vatSummary calculates VAT correctly', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const result = vatSummary([invoice]);

  assert.ok(result.value.length > 0);
  const { rate, base, vat } = result.value[0];
  const expectedVat = Math.round(base * rate / 100);
  assert.equal(vat, expectedVat);
});

