// Late Fee Tests
import { lateFee } from '../src/reports.js';

test('lateFee returns 0 when invoice is not overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-10-01');
  const fee = lateFee(invoice, '2026-10-07');

  assert.equal(fee, 0);
});

test('lateFee returns 0 when due date equals asOf date', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-07');
  const fee = lateFee(invoice, '2026-10-07');

  assert.equal(fee, 0);
});

test('lateFee returns number', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const fee = lateFee(invoice, '2026-10-07');

  assert.equal(typeof fee, 'number');
});

test('lateFee returns 0 when invoice is fully paid', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const { total } = invoiceTotals(invoice);
  const paid = recordPayment(invoice, { amount: total, date: '2026-09-05' }).value;
  const fee = lateFee(paid, '2026-10-07');

  assert.equal(fee, 0);
});

test('lateFee calculates for issued invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const fee = lateFee(invoice, '2026-10-07');

  assert.ok(fee > 0);
});

test('lateFee calculates for partially_paid invoice', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const paid = recordPayment(invoice, { amount: 5000, date: '2026-09-05' }).value;
  const fee = lateFee(paid, '2026-10-07');

  assert.ok(fee > 0);
});

test('lateFee returns 0 for draft invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const fee = lateFee(draft, '2026-10-07');

  assert.equal(fee, 0);
});

test('lateFee calculates correctly for 1 day overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-06');
  const { total } = invoiceTotals(invoice);
  const fee = lateFee(invoice, '2026-10-07');

  const expectedFee = Math.round(total * 0.0004 * 1);
  assert.equal(fee, expectedFee);
});

test('lateFee calculates correctly for multiple days overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const { total } = invoiceTotals(invoice);
  const fee = lateFee(invoice, '2026-10-07');

  const daysOverdue = 6;
  const expectedFee = Math.round(total * 0.0004 * daysOverdue);
  assert.equal(fee, expectedFee);
});

test('lateFee increases with more days overdue', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const fee1 = lateFee(invoice, '2026-10-02');
  const fee2 = lateFee(invoice, '2026-10-07');

  assert.ok(fee2 > fee1);
});

test('lateFee increases with larger balance due', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
