  assert.ok(fee >= 0);
});

test('lateFee with paid invoice status', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const { total } = invoiceTotals(invoice);
  const paid = recordPayment(invoice, { amount: total, date: '2026-09-05' }).value;

  const fee = lateFee(paid, '2026-10-10');

  assert.equal(fee, 0);
});

test('lateFee respects invoice status', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const fee = lateFee(draft, '2026-10-07');

  assert.equal(fee, 0);
});

test('lateFee calculation with partial payment', () => {
  const invoice = createAndIssueInvoice('C-001', '2026-09-01');
  const { total } = invoiceTotals(invoice);
  const halfPayment = Math.floor(total / 2);
  const paid = recordPayment(invoice, { amount: halfPayment, date: '2026-09-05' }).value;

  const daysOverdue = 6;
  const remainingDue = total - halfPayment;
  const expectedFee = Math.round(remainingDue * 0.0004 * daysOverdue);

  const fee = lateFee(paid, '2026-10-07');

  assert.equal(fee, expectedFee);
});

